4. { "ResponseCode": "200", "URL": "https://pltngwcdevstt6poc.blob.core.windows.net/aig-exchange/ae9e3c98655e1d792c3bed75?", "TOKEN": "sv=2020-12-06&sr=d&sp=rl&st=2023-11-11T12:12:30Z&se=2023-11-27T12:12:30Z&spr=https&sig=fEpBz15o7KtjgCvWDKsujr2F7ClhdZht%2F4EYTcWPujE%3D&sdd=1" }
